import json


def main(env):
    resp = env.http_get("https://api.example.com/alert")
    if not 200 <= resp["status"] <= 299:
        raise RuntimeError(f"unexpected status {resp['status']}")
    data = json.loads(resp["body"])
    urgent = data["urgent"]
    msg = data["msg"]
    if not isinstance(urgent, bool):
        raise RuntimeError("urgent must be a boolean")
    if not isinstance(msg, str):
        raise RuntimeError("msg must be text")
    if urgent:
        prompt = "Escalate: " + msg
        if len(prompt.split()) > 100:
            raise RuntimeError("prompt exceeds 100 words")
        return env.model("mock-1", prompt)
    return "No action"
